package com.example.lending.application.service;

import com.example.lending.application.port.in.ListMemberLoanHistoryUseCase;
import com.example.lending.application.port.out.LoadAllLoansPort;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.Loan;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.UUID;

@Service
@Transactional(readOnly = true)
public class ListMemberLoanHistoryService implements ListMemberLoanHistoryUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadAllLoansPort loadAllLoansPort;
    private final LoadBookPort loadBookPort;

    public ListMemberLoanHistoryService(LoadMemberPort loadMemberPort, LoadAllLoansPort loadAllLoansPort,
                                        LoadBookPort loadBookPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadAllLoansPort = loadAllLoansPort;
        this.loadBookPort = loadBookPort;
    }

    @Override
    public List<LoanHistoryItem> listHistory(UUID memberId) {
        loadMemberPort.loadMember(memberId).orElseThrow(() -> new MemberNotFoundException(memberId));

        return loadAllLoansPort.loadAllLoans(memberId).stream()
                .map(this::toItem)
                .toList();
    }

    private LoanHistoryItem toItem(Loan loan) {
        Book book = loadBookPort.loadBook(loan.getBookId())
                .orElseThrow(() -> new BookNotFoundException(loan.getBookId()));
        boolean returned = !loan.isActive();
        return new LoanHistoryItem(loan.getId(), book.getTitle(), loan.getLoanedAt(), loan.getReturnedAt(),
                returned ? loan.lateFee() : null);
    }
}

