import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Component
public class LoanPersistenceAdapter implements SaveLoanPort, LoadLoanPort, CountActiveLoansPort, LoadActiveLoansPort,
        LoadAllLoansPort {

    private final LoanJpaRepository loanJpaRepository;
    private final LoanMapper loanMapper = new LoanMapper();

    public LoanPersistenceAdapter(LoanJpaRepository loanJpaRepository) {
        this.loanJpaRepository = loanJpaRepository;
    }

    @Override
    public void saveLoan(Loan loan) {
        loanJpaRepository.save(loanMapper.toEntity(loan));
    }

    @Override
    public Optional<Loan> loadLoan(UUID loanId) {
        return loanJpaRepository.findById(loanId).map(loanMapper::toDomain);
    }

    @Override
    public long countActiveLoans(UUID memberId) {
        return loanJpaRepository.countByMemberIdAndReturnedAtIsNull(memberId);
    }

    @Override
    public ActiveLoanPage loadActiveLoans(UUID memberId, int page, int size) {
        Page<LoanJpaEntity> loans = loanJpaRepository.findByMemberIdAndReturnedAtIsNull(memberId,
                PageRequest.of(page, size, Sort.by("loanedAt", "id")));
        return new ActiveLoanPage(loans.map(loanMapper::toDomain).getContent(), loans.getTotalElements());
    }

    @Override
    public List<Loan> loadAllLoans(UUID memberId) {
        return loanJpaRepository.findByMemberId(memberId, Sort.by(Sort.Direction.DESC, "loanedAt", "id")).stream()
                .map(loanMapper::toDomain)
                .toList();
    }
}

